resources=[]
def add(id,title,disposition,reason,paths,scope='Source/manifests or explicitly identified excerpts inspected; not a new acceptance or runtime audit'):
 files=[]
 for p in paths:
  p=Path(p);p=p if p.is_absolute() else ROOT/p
  files.append(dict(path=str(p).replace('\\','/'),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size))
 resources.append(dict(id=id,title=title,disposition=disposition,reason=reason,inspection=scope,files=files))
